using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Windows.Forms;using System.Runtime.InteropServices;
internal static class TestDesktopPreferences {
 static int checks;static readonly JavaScriptSerializer json=new JavaScriptSerializer();
 static readonly string[] Right={"quota","desktop","notes","tasks","countdown","links","calculator"},Left={"network","Weather","Music","Focus","Folders","System","Tools","Life"};
 static void Check(bool value,string name){if(!value)throw new Exception(name);Console.WriteLine("PASS "+name);checks++;}
 static void Reject(Action operation,string name){bool refused=false;try{operation();}catch(ArgumentException){refused=true;}catch(IOException){refused=true;}Check(refused,name);}
 static Dictionary<string,object> Snapshot(DesktopPreferences settings){return (Dictionary<string,object>)settings.Snapshot();}
 static Dictionary<string,object> FileMap(string root,string name){return json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(root,name)));}
 static void Apply(DesktopPreferences settings,string key,object value){settings.Apply(new Dictionary<string,object>{{key,value}},settings.Revision);}
 [DllImport("user32.dll",SetLastError=true)]static extern bool RegisterHotKey(IntPtr window,int id,uint modifiers,uint key);
 [DllImport("user32.dll")]static extern bool UnregisterHotKey(IntPtr window,int id);
 [STAThread]static int Main(string[] args){string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"desktop-preferences-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
  File.WriteAllText(Path.Combine(root,"theme.txt"),"Astro");File.WriteAllText(Path.Combine(root,"paused.txt"),"true");File.WriteAllText(Path.Combine(root,"shelf-state.json"),"{\"tasks\":[{\"id\":\"keep\",\"text\":\"Existing task\",\"done\":false}],\"links\":[],\"extensionField\":\"keep me\"}");
  var settings=new DesktopPreferences(root);Check(settings.Current.theme=="Astro"&&settings.Current.manualPaused,"legacy theme and manual pause are preserved");Check(!settings.IsFirstRun,"existing user data does not trigger the first-run guide");
  string fresh=Path.Combine(root,"fresh");Directory.CreateDirectory(fresh);var freshSettings=new DesktopPreferences(fresh);Check(freshSettings.IsFirstRun,"an empty installation is eligible for the first-run guide");Apply(freshSettings,"welcomeShown",true);Check(new DesktopPreferences(fresh).Current.welcomeShown&&!new DesktopPreferences(fresh).IsFirstRun,"first-run acknowledgement persists without enabling optional services");
  Check(!settings.Current.pauseOnBattery&&settings.Current.pauseOnPowerSaver,"compatible defaults do not enable battery pause");
  Apply(settings,"glassOpacity",75);Check(settings.Current.glassOpacity==75&&File.ReadAllText(Path.Combine(root,"paused.txt"))=="true","appearance save preserves manual pause");
  settings.Apply(new Dictionary<string,object>{{"hiddenCards",new[]{"quota"}},{"cardOrder",Right.Reverse().ToArray()},{"hiddenLeftCards",Left},{"leftCardOrder",Left.Reverse().ToArray()}},settings.Revision);
  var shelf=FileMap(root,"shelf-state.json");Check((string)shelf["extensionField"]=="keep me"&&json.Serialize(shelf["tasks"]).Contains("Existing task"),"component settings preserve tasks and unknown fields");
  Check(json.Serialize(shelf["cardOrder"])==json.Serialize(Right.Reverse().ToArray()),"right component order persists");Check(json.Serialize(Snapshot(settings)["leftCardOrder"])==json.Serialize(Left.Reverse().ToArray()),"left order and visibility persist independently");
  Reject(()=>Apply(settings,"hiddenCards",Right),"right side cannot hide every management entry");Reject(()=>Apply(settings,"cardOrder",new[]{"desktop","desktop"}),"duplicate or incomplete order is rejected");
  Apply(settings,"cardOrder",new string[0]);Apply(settings,"leftCardOrder",new string[0]);Check(json.Serialize(Snapshot(settings)["cardOrder"])==json.Serialize(Right)&&json.Serialize(Snapshot(settings)["leftCardOrder"])==json.Serialize(Left),"empty order resets only ordering to original defaults");
  long stale=settings.Revision;File.WriteAllText(Path.Combine(root,"theme.txt"),"Sky");Reject(()=>settings.Apply(new Dictionary<string,object>{{"theme","Astro"}},stale),"external edit invalidates stale save revision");Check(File.ReadAllText(Path.Combine(root,"theme.txt"))=="Sky","conflicting save never overwrites external change");
  Apply(settings,"monitors",new[]{new MonitorPreferences{id="disconnected-test-monitor",enabled=true,dockOffset=42,left=false}});var reopened=new DesktopPreferences(root);Check(reopened.ForMonitor("disconnected-test-monitor",false).dockOffset==42&&!reopened.ForMonitor("disconnected-test-monitor",false).left,"disconnected monitor preferences survive reload");Check(!reopened.ForMonitor("new-secondary",false).enabled&&reopened.ForMonitor("new-primary",true).enabled,"new screens inherit primary-only activation");
  string original=File.ReadAllText(Path.Combine(root,"shelf-state.json"));File.WriteAllText(Path.Combine(root,"shelf-state.json"),"{broken");Check(!String.IsNullOrEmpty(Convert.ToString(Snapshot(settings)["error"])),"corrupt sidecar is reported without crashing snapshot");Reject(()=>Apply(settings,"glassOpacity",80),"corrupt sidecar blocks writes");Check(File.ReadAllText(Path.Combine(root,"shelf-state.json"))=="{broken","corrupt content is retained for repair");File.WriteAllText(Path.Combine(root,"shelf-state.json"),original);settings.Reload();Apply(settings,"glassOpacity",80);Check(settings.Current.glassOpacity==80,"repair restores ordinary saving");
  string desktop=File.ReadAllText(Path.Combine(root,"desktop-settings.json"));File.WriteAllText(Path.Combine(root,"desktop-settings.json"),"{\"version\":999}");Check(!String.IsNullOrEmpty(Convert.ToString(Snapshot(settings)["error"])),"unsupported future configuration remains readable as an error");Reject(()=>Apply(settings,"theme","Sky"),"unsupported future configuration is not overwritten");File.WriteAllText(Path.Combine(root,"desktop-settings.json"),desktop);settings.Reload();
  bool rolledBack=false;string oldHotkey=settings.Current.hotkey;settings.PrepareHotkey=value=>{File.WriteAllText(Path.Combine(root,"theme.txt"),"Astro");return ()=>rolledBack=true;};Reject(()=>Apply(settings,"hotkey","Ctrl+Alt+A"),"edit racing provisional hotkey registration rejects the transaction");Check(rolledBack&&settings.Current.hotkey==oldHotkey,"failed settings transaction releases provisional hotkey and preserves original configuration");settings.PrepareHotkey=null;settings.Reload();
  var signals=new RuntimeSignals{battery=true,locked=true,displayOff=true,remote=true,powerSaver=true};var state=new DesktopPreferenceState{manualPaused=true,pauseOnBattery=true,reducedMotion=true};var reasons=RuntimePolicy.Reasons(state,signals,true,true,true);Check(reasons.Length==9&&reasons.Distinct().Count()==9,"all simultaneous pause reasons form a unique union");signals=new RuntimeSignals();reasons=RuntimePolicy.Reasons(state,signals,false,false,true);Check(reasons.Contains("手动暂停")&&reasons.Length==2,"clearing system reasons does not clear manual pause");state.manualPaused=false;state.reducedMotion=false;Check(RuntimePolicy.Reasons(state,signals,false,false,true).Length==0,"animation resumes only after all reasons are cleared");Check(RuntimePolicy.Reasons(state,signals,true,false,true).Length==1&&RuntimePolicy.Reasons(state,signals,false,false,true).Length==0,"coverage is evaluated independently per monitor");state.pauseOnBattery=false;signals.battery=true;Check(RuntimePolicy.Reasons(state,signals,false,false,true).Length==0,"disabled battery policy remains disabled");
  var spec=HotkeyBinding.Parse("Ctrl+Alt+Space");Check(spec.modifiers==3&&spec.key==(uint)Keys.Space,"configured shortcut parses into native modifier and key values");Reject(()=>HotkeyBinding.Parse("Ctrl+Ctrl+A"),"duplicate shortcut modifiers are rejected");Reject(()=>HotkeyBinding.Parse("A"),"unmodified global shortcut is rejected");
  if(Array.IndexOf(args,"--native-hotkey")>=0)using(var owner=new Form())using(var competitor=new Form())using(var binding=new HotkeyBinding(owner.Handle)){
   binding.Configure("Ctrl+Alt+Shift+F24");Check(binding.Matches(Message.Create(owner.Handle,0x312,new IntPtr(0x5A11),IntPtr.Zero)),"initial global shortcut is registered");bool reserved=RegisterHotKey(competitor.Handle,0x5A20,7|0x4000,(uint)Keys.F23);Check(reserved,"isolated conflicting shortcut is reserved");try{Reject(()=>binding.Prepare("Ctrl+Alt+Shift+F23"),"occupied shortcut is rejected");binding.Commit();Check(binding.Matches(Message.Create(owner.Handle,0x312,new IntPtr(0x5A11),IntPtr.Zero)),"failed rebind keeps the original shortcut after later commit");}finally{if(reserved)UnregisterHotKey(competitor.Handle,0x5A20);}
   Action rollback=binding.Prepare("Ctrl+Alt+Shift+F22");rollback();binding.Commit();Check(binding.Matches(Message.Create(owner.Handle,0x312,new IntPtr(0x5A11),IntPtr.Zero)),"failed persistence rolls back provisional shortcut registration");
  }
  int hostAt=Array.IndexOf(args,"--shelf-host");if(hostAt>=0&&hostAt+1<args.Length){
   var assembly=System.Reflection.Assembly.LoadFrom(Path.GetFullPath(args[hostAt+1]));var type=assembly.GetType("FileShelf",true);var save=type.GetMethod("SaveState",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
   File.WriteAllText(Path.Combine(root,"shelf-state.json"),"{broken");using(var shelfForm=(Form)Activator.CreateInstance(type,new object[]{root,false}))Reject(()=>{try{save.Invoke(shelfForm,null);}catch(System.Reflection.TargetInvocationException ex){throw ex.InnerException;}},"native shelf refuses save after corrupt read");Check(File.ReadAllText(Path.Combine(root,"shelf-state.json"))=="{broken","native shelf preserves corrupt bytes");
   File.WriteAllText(Path.Combine(root,"shelf-state.json"),original);using(var shelfForm=(Form)Activator.CreateInstance(type,new object[]{root,false})){
    save.Invoke(shelfForm,null);var receive=type.GetMethod("Receive",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);var expanded=type.GetField("expanded",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);var dismiss=type.GetMethod("DismissTransient");
    foreach(var action in new[]{"mode","pin-mode"}){receive.Invoke(shelfForm,new object[]{"{\"action\":\""+action+"\",\"value\":\"manage\"}"});Check(File.ReadAllText(Path.Combine(root,"workspace.request"))=="settings"&&!(bool)expanded.GetValue(shelfForm),"legacy "+action+" manager routes to unified settings and collapses");File.Delete(Path.Combine(root,"workspace.request"));}
    receive.Invoke(shelfForm,new object[]{"{\"action\":\"hover-mode\",\"value\":\"manage\"}"});Check(!File.Exists(Path.Combine(root,"workspace.request")),"hovering manager never opens or focuses settings");
    receive.Invoke(shelfForm,new object[]{"{\"action\":\"hover-mode\",\"value\":\"tasks\"}"});dismiss.Invoke(shelfForm,null);Check(!(bool)expanded.GetValue(shelfForm),"temporary shelf closes when another workspace opens");
    receive.Invoke(shelfForm,new object[]{"{\"action\":\"hover-mode\",\"value\":\"tasks\"}"});receive.Invoke(shelfForm,new object[]{"{\"action\":\"pin\"}"});dismiss.Invoke(shelfForm,null);Check((bool)expanded.GetValue(shelfForm),"explicitly pinned shelf survives workspace dismissal");
   }Check((string)FileMap(root,"shelf-state.json")["extensionField"]=="keep me","native shelf ordinary save preserves unknown fields");
  }
  Check(!Directory.EnumerateFiles(root,"*.pending-*").Any(),"atomic saves leave no pending files");Console.WriteLine("Completed "+checks+" desktop preference/runtime checks.");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{Directory.Delete(root,true);}}
}
